from html.parser import HTMLParser
from urllib.request import build_opener, ProxyHandler, HTTPRedirectHandler
from urllib.parse import urljoin, urlsplit
class Direct(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        if urlsplit(newurl).netloc == '127.0.0.1:41639':
            return super().redirect_request(req, fp, code, msg, headers, newurl)
class Page(HTMLParser):
    def __init__(self):
        super().__init__()
        self.anchor = None
        self.links = []
        self.hidden = False
    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.anchor = [dict(attrs).get('href'), '']
        if tag in ('script', 'style', 'head'):
            self.hidden = True
        if tag in ('html','meta'):
            data = dict(attrs)
            if 'lang' in data or data.get('name') == 'docusaurus_locale':
                print(tag, data)
    def handle_data(self, data):
        if self.anchor: self.anchor[1] += data
        if not self.hidden and data.strip(): print(repr(data))
    def handle_endtag(self, tag):
        if tag == 'a' and self.anchor:
            self.links.append(self.anchor)
            self.anchor = None
        if tag in ('script', 'style', 'head'):
            self.hidden = False
opener = build_opener(ProxyHandler({}), Direct())
home = 'http://127.0.0.1:41639/it/'
def read(url):
    with opener.open(url) as res:
        print(res.status, res.url)
        page = Page()
        page.feed(res.read().decode())
        print(page.links)
        return page.links
links = read(home)
targets = {urljoin(home, href) for href, label in links if label.strip() == 'Manuale del turno 2.0'}
assert len(targets) == 1, targets
for url in targets:
    assert urlsplit(url).netloc == '127.0.0.1:41639'
    read(url)
